SELECT  FROM t_accounting_rule_bundle_ver
WHERE status = 'APPROVED' AND effective_from <= #{asOf}
ORDER BY effective_from, bundle_id, bundle_ver

mapper.update:
UPDATE t_accounting_rule_bundle_ver
SET status = #{status}, checker_id = #{checkerId}, approved_time = #{approvedTime}, effective_to = #{effectiveTo},
    update_time = #{now}
WHERE id = #{ver.id} AND status = #{ver.status}
